        guide = "1. Travel to Azj-Kahet and enter the Weaver's Lair.\n2. Find Yamas the Provider, the nerubian supplier, on the platform (55.2, 41.4).\n3. Buy the Notorious Thread's Hearthstone for 3,000 gold.\n4. It works as an extra Hearthstone: it takes you to your Hearthstone location (talk to an innkeeper elsewhere to change the destination).",
