        guide = "1. This vendor only appears in Valdrakken during the Dragonflight Timewalking week (Turbulent Timeways).\n2. Head to the Bronze Enclave, eastern part of the city, platform (81.4, 47.3).\n3. Talk to Xydan and buy the Oathstone Fragment for 500 Timewarped Badges.\n4. Use it to skip a smooth stone across the water and watch it bounce (cooldown 5 sec).",
