    [225659] = {
        name = "Arathi Book Collection",
        sourceType = "TREASURE",
        zone = "Hallowfall",
        coords = "40.0, 51.1",
        target = "Loremaster's Reward (table next to Ryfus Sacredpyr, Holy Flame Church, Mereldar)",
        cost = "Free (requires level 73+ and answering the 6 lore questions correctly)",
        difficulty = "Medium",
        guide = "1. Travel to Mereldar in Hallowfall and enter the Holy Flame Church (40.0, 51.1).\n2. Talk to Ryfus Sacredpyr and correctly answer the 6 Arathi Loremaster questions.\n3. Collect the 6 lore books scattered around Hallowfall to check the answers.\n4. If you get them all right, the Loremaster's Reward chest appears on the table next to him — open it to receive the Arathi Book Collection.\n5. Use the toy to sit at a table and read a book (cooldown 30 sec).",
        waypoint = "/way Hallowfall 40.0 51.1 Loremaster's Reward"
    },
    [224552] = {
        name = "Cave Spelunker's Torch",
        sourceType = "TREASURE",
        zone = "Hallowfall",
        coords = "57.5, 27.4",
        target = "Illuminated Footlocker (chest inside the dark cave at 58.4, 27.2 — requires the Glimmering Illumination buff)",
        cost = "Free",
        difficulty = "Medium",
        guide = "1. Travel to the cave entrance northeast of Hallowfall (57.5, 27.4).\n2. Inside the cave it is dark: catch the 5 light motes emitted by the moth (glowing wisp) to get the Glimmering Illumination buff (2 min).\n3. With the buff active, the Illuminated Footlocker becomes visible at the back of the cave (58.4, 27.2).\n4. Open the chest to receive the Cave Spelunker's Torch.\n5. Use it to light a torch (useful in dark caves).",
        waypoint = "/way Hallowfall 57.5 27.4 Illuminated Footlocker (cave entrance)"
    },
    [224554] = {
        name = "Silver Linin' Scepter",
        sourceType = "TREASURE",
        zone = "Hallowfall",
        coords = "45.9, 45.1",
        target = "Sunken Cache (sunken chest off the coast of Mereldar — requires talking to the 4 Sky Captains first)",
        cost = "Free",
        difficulty = "Medium",
        guide = "1. Talk to the 4 Sky Captains patrolling Hallowfall by zeppelin: Clairmonte, Dornald, Onaro and Aerthin — aboard their ships.\n2. After talking to all of them, swim down to the bottom of the bay off Mereldar (45.9, 45.1).\n3. The Sunken Cache becomes lootable underwater.\n4. Open the chest to receive the Silver Linin' Scepter.\n5. Use it to call the wind to your arms — your feet don't touch the ground!",
        waypoint = "/way Hallowfall 45.9 45.1 Sunken Cache"
    },
    [209858] = {
        name = "Dreamsurge Remnant",
        sourceType = "EVENT",
        zone = "The Waking Shores",
        coords = "58.4, 67.8",
        target = "Celestine of the Harvest (rotates weekly among The Waking Shores, Ohn'ahran Plains, The Azure Span and Thaldraszus — in the right week she is at 58.4, 67.8)",
        cost = "500 Dreamsurge Coalescence",
        difficulty = "Easy",
        guide = "1. The Dreamsurge event happens in one Dragon Isles zone per week — check the in-game map for the active zone (the event icon marks the location).\n2. In The Waking Shores week, Celestine of the Harvest is at (58.4, 67.8).\n3. Complete the Dreamsurge objectives in that zone to earn Dreamsurge Coalescence.\n4. Talk to Celestine and buy the Dreamsurge Remnant for 500 Coalescence.\n5. Use it to relive the memory of a Dreamsurge.",
        waypoint = "/way The Waking Shores 58.4 67.8 Celestine of the Harvest"
    },

